dtsPropsFor.Button:
/** primary = accent fill, one per view; secondary = outline (default); destructive = red fill, only inside a confirm dialog. */
  variant?: "primary" | "secondary" | "destructive";
  /** Shows a spinner and disables the button. */
  loading?: boolean;
  /** Text shown in place of children while loading. */
  loadingLabel?: string;
  disabled?: boolean;
  type?: "button" | "submit" | "reset";
  onClick?: (event: React.MouseEvent<HTMLButtonElement>) => void;
  className?: string;
  id?: string;
  style?: React.CSSProperties;
  children?: React.ReactNode;
  /** Every other native <button> attribute is passed through. */
  [attribute: string]: unknown;

dtsPropsFor.Input:
/** Uppercase mono caption above the field. */
  label?: string;
  /** Helper line under the field. */
  hint?: string;
  /** Error line under the field; replaces hint and turns the border red. */
  error?: string;
  /** Render the value in the mono font (paths, codes, commands). */
  mono?: boolean;
  value?: string;
  defaultValue?: string;
  placeholder?: string;
  type?: string;
  name?: string;
  disabled?: boolean;
  readOnly?: boolean;
  onChange?: (event: React.ChangeEvent<HTMLInputElement>) => void;
  className?: string;
  id?: string;
  style?: React.CSSProperties;
  /** Every other native <input> attribute is passed through. */
  [attribute: string]: unknown;

dtsPropsFor.AgentBadge:
/** The AI coding agent running in a Session. */
  agent: {
    agent: "CLAUDE" | "CODEX" | "AIDER" | "GEMINI" | "VIBE" | "ANTIGRAVITY";
    /** On a turn now: shows the pulsing dot. */
    working: boolean;
    toolUses: number;
    tokens?: number;
    costUsd?: number;
  };
  /** Also show the usage text (tool calls, tokens, cost) after the name. */
  usage?: boolean;

dtsPropsFor.PromptChoices:
/** A WAITING Session; one button is rendered per promptOptions entry (at most 6). Renders nothing when there are none. */
  session: {
    id: string;
    machine: string;
    name: string;
    state: "CREATED" | "IDLE" | "RUNNING" | "WAITING" | "STALLED" | "COMPLETED" | "FAILED" | "INTERRUPTED" | "DISCONNECTED";
    prompt?: string;
    /** keys is the single key the option types, e.g. "1" or "y". */
    promptOptions?: { label: string; keys: string }[];
  };
  /** Called after an answer was sent to the Session. */
  onAnswered?: () => void;

dtsPropsFor.OutputSearchToggle:
/** The Session whose saved output can be opted into search; outputSearch sets the initial checked state. */
  session: {
    id: string;
    machine: string;
    name: string;
    state: "CREATED" | "IDLE" | "RUNNING" | "WAITING" | "STALLED" | "COMPLETED" | "FAILED" | "INTERRUPTED" | "DISCONNECTED";
    outputSearch?: boolean;
  };

